arguments.command:
bash -lc 'set -e; sed -i "/buf[len] = 0;/i\    if (len >= size) {
        xmlChar *new_buf;
        size_t new_size = size * 2;
        if (new_size < len + 1) new_size = len + 1;
        new_buf = (xmlChar *) xmlRealloc(buf, new_size);
        if (new_buf == NULL) {
            xmlFree (buf);
            return;
        }
        buf = new_buf;
        size = new_size;
    }" /src/libxml2/parser.c; cd /src/libxml2; secb build; secb repro'
